// Provider API client.

export interface ClientOptions {
  endpoint: string;
  timeoutMs?: number;
}

export async function fetchWithTimeout(options: ClientOptions): Promise<globalThis.Response> {
  const res = await fetchWithRetry(options.endpoint, { attempts: 3 });
  return res;
}
